body:
Ok, thanks for the 411.  I still find the code a bit confusing.  I've attempted a suggested rewrite.  Please use it if you think it's better and it works, if not feel free to ignore me!  I think it's a littler clearer to read through, the negatives mislead me first time through.
```
Old:

        for _, imageInfo := range pullStructs {
                if options.Writer != nil && imageInfo.srcRef.Transport().Name() != DockerArchive && imageInfo.srcRef.Transport().Name() != OCIArchive && imageInfo.srcRef.Transport().Name() != DirTransport {
                        io.WriteString(options.Writer, fmt.Sprintf("Trying to pull %s...\n", imageInfo.image))
                }
                if err = cp.Image(policyContext, imageInfo.dstRef, imageInfo.srcRef, copyOptions); err != nil {
                        if options.Writer != nil && imageInfo.srcRef.Transport().Name() != DockerArchive && imageInfo.srcRef.Transport().Name() != OCIArchive && imageInfo.srcRef.Transport().Name() != DirTransport {
                                io.WriteString(options.Writer, "Failed\n")
                        }
                } else {
                        return imageInfo.image, nil
                }
        }
        return "", errors.Wrapf(err, "error pulling image from %q", imgName)

###############

New:

        for _, imageInfo := range pullStructs {
                // Only print header if pulling from a registry.
                if options.Writer == nil ||  imageInfo.srcRef.Transport().Name() == DockerArchive || imageInfo.srcRef.Transport().Name() == OCIArchive || imageInfo.srcRef.Transport().Name() == DirTransport {
                        return imageInfo.image, nil
                }
                io.WriteString(options.Writer, fmt.Sprintf("Trying to pull %s...\n", imageInfo.image))
                }
                if err = cp.Image(policyContext, imageInfo.dstRef, imageInfo.srcRef, copyOptions); err != nil {
                        io.WriteString(options.Writer, "Failed\n")
                } else {
                        return imageInfo.image, nil
                }
        }
        return "", errors.Wrapf(err, "error pulling image from %q", imgName)

